#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Try single operation: element at pos goes to position placed
        // In new array, p[pos] goes to: if pos>=n-y (in suffix): pos-(n-y)
        // if x<=pos<n-y (in middle): y + (pos - x)
        // if pos<x (in prefix): (n-x) + pos
        bool done=false;
        for(int x=1;x<n&&!done;x++) for(int y=1;x+y<n&&!done;y++){
            int newpos;
            if(pos>=n-y) newpos=pos-(n-y);
            else if(pos>=x) newpos=y+(pos-x);
            else newpos=(n-x)+pos;
            if(newpos==placed){doOp(x,y);done=true;}
        }
        if(done) continue;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
